using UnityEditor;using System.IO;
[InitializeOnLoad]public static class FinalSkinMobileImport{
static FinalSkinMobileImport(){EditorApplication.delayCall+=()=>{var p="Assets/Girl Player/Realistic Skin/";if(!File.Exists(p+"Applied.txt")||File.Exists(p+"Mobile Import.txt"))return;foreach(var f in new[]{"Skin Base Color.png","Skin Normal.png"}){var t=AssetImporter.GetAtPath(p+f) as TextureImporter;foreach(var platform in new[]{"Android","iPhone"}){var s=t.GetPlatformTextureSettings(platform);s.overridden=true;s.maxTextureSize=2048;s.format=TextureImporterFormat.ASTC_6x6;s.compressionQuality=70;t.SetPlatformTextureSettings(s);}t.SaveAndReimport();}File.WriteAllText(p+"Mobile Import.txt","4K source maps; Android/iOS 2K ASTC 6x6 overrides; mipmaps enabled. Geometry unchanged. Device performance not benchmarked.");};}}
